SET ROLE model_authenticated; SELECT set_config('model.subject','bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb',false);
SELECT dm_model.ok('UPDATE_CONTENT_GRANTED',NOT has_column_privilege(current_user,'dm_model.messages','content','UPDATE'));
SELECT dm_model.ok('recipient_read',(SELECT count(*)=2 FROM dm_model.messages));
SELECT dm_model.ok('content_update_denied',dm_model.denied($q$UPDATE dm_model.messages SET content='tampered' WHERE id='00000000-0000-0000-0000-000000000001'$q$));
SELECT dm_model.ok('sender_reassignment_denied',dm_model.denied($q$UPDATE dm_model.messages SET sender_id='cccccccc-cccc-cccc-cccc-cccccccccccc' WHERE id='00000000-0000-0000-0000-000000000001'$q$));
SELECT dm_model.ok('receiver_reassignment_denied',dm_model.denied($q$UPDATE dm_model.messages SET receiver_id='cccccccc-cccc-cccc-cccc-cccccccccccc' WHERE id='00000000-0000-0000-0000-000000000001'$q$));
SELECT dm_model.ok('recipient_ack',dm_model.affected($q$UPDATE dm_model.messages SET read_at='2026-01-01Z' WHERE id='00000000-0000-0000-0000-000000000001'$q$)=1);
SELECT dm_model.ok('delete_denied',dm_model.denied($q$DELETE FROM dm_model.messages WHERE id='00000000-0000-0000-0000-000000000001'$q$));
SELECT set_config('model.subject','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',false);
SELECT dm_model.ok('sender_read',(SELECT count(*)=1 FROM dm_model.messages));
SELECT dm_model.ok('sender_ack_zero',dm_model.affected($q$UPDATE dm_model.messages SET read_at=NULL WHERE id='00000000-0000-0000-0000-000000000001'$q$)=0);
SELECT dm_model.ok('valid_insert',dm_model.affected($q$INSERT INTO dm_model.messages(sender_id,receiver_id,content) VALUES('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','new')$q$)=1);
SELECT dm_model.ok('forged_sender_denied',dm_model.denied($q$INSERT INTO dm_model.messages(sender_id,receiver_id,content) VALUES('cccccccc-cccc-cccc-cccc-cccccccccccc','bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','forged')$q$));
SELECT dm_model.ok('insert_read_at_denied',dm_model.denied($q$INSERT INTO dm_model.messages(sender_id,receiver_id,content,read_at) VALUES('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','fake ack',now())$q$));
SELECT dm_model.ok('reverse_block_denied',dm_model.denied($q$INSERT INTO dm_model.messages(sender_id,receiver_id,content) VALUES('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','dddddddd-dddd-dddd-dddd-dddddddddddd','blocked')$q$));
SELECT set_config('model.subject','dddddddd-dddd-dddd-dddd-dddddddddddd',false);
SELECT dm_model.ok('forward_block_denied',dm_model.denied($q$INSERT INTO dm_model.messages(sender_id,receiver_id,content) VALUES('dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','blocked')$q$));
SELECT set_config('model.subject','cccccccc-cccc-cccc-cccc-cccccccccccc',false);
SELECT dm_model.ok('third_party_read',NOT EXISTS(SELECT 1 FROM dm_model.messages WHERE id='00000000-0000-0000-0000-000000000001'));
SELECT dm_model.ok('third_party_ack_zero',dm_model.affected($q$UPDATE dm_model.messages SET read_at=now() WHERE id='00000000-0000-0000-0000-000000000001'$q$)=0);
SELECT set_config('model.subject','',false);
SELECT dm_model.ok('missing_identity_read',(SELECT count(*)=0 FROM dm_model.messages));
SELECT dm_model.ok('missing_identity_insert',dm_model.denied($q$INSERT INTO dm_model.messages(sender_id,receiver_id,content) VALUES('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','no auth')$q$));
RESET ROLE; SET ROLE model_anon;
SELECT dm_model.ok('anonymous_read_denied',dm_model.denied('SELECT * FROM dm_model.messages'));
RESET ROLE; BEGIN; SET LOCAL ROLE model_authenticated; SELECT set_config('model.subject','bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb',true); UPDATE dm_model.messages SET read_at=now() WHERE id='00000000-0000-0000-0000-000000000003'; ROLLBACK;
SELECT dm_model.ok('rollback_and_committed_integrity',(SELECT read_at IS NULL AND content='rollback CB' FROM dm_model.messages WHERE id='00000000-0000-0000-0000-000000000003') AND (SELECT content='committed AB' FROM dm_model.messages WHERE id='00000000-0000-0000-0000-000000000001'));
